import{_ as p,r as n,o,c,e as a,a as l,s as i}from"./chunks/framework.CXcwiNg-.js";const v=JSON.parse('{"title":"Разрешения - October CMS - 3.x","titleTemplate":false,"description":"Узнайте, как управлять разрешениями в панели управления.","frontmatter":{"subtitle":"Узнайте, как управлять разрешениями в панели управления."},"headers":[{"level":2,"title":"Коды разрешений","slug":"коды-разрешении","link":"#коды-разрешении","children":[{"level":3,"title":"Вложенные разрешения","slug":"вложенные-разрешения","link":"#вложенные-разрешения","children":[]}]},{"level":2,"title":"Уровни доступа","slug":"уровни-доступа","link":"#уровни-доступа","children":[{"level":3,"title":"Суперпользователи","slug":"суперпользователи","link":"#суперпользователи","children":[]},{"level":3,"title":"Роли","slug":"роли","link":"#роли","children":[]},{"level":3,"title":"Иерархия ролей","slug":"иерархия-ролеи","link":"#иерархия-ролеи","children":[]}]},{"level":2,"title":"Регистрация разрешений","slug":"регистрация-разрешении","link":"#регистрация-разрешении","children":[]},{"level":2,"title":"Ограничение доступа к страницам панели управления","slug":"ограничение-доступа-к-страницам-панели-управления","link":"#ограничение-доступа-к-страницам-панели-управления","children":[]},{"level":2,"title":"Ограничение доступа к функциям","slug":"ограничение-доступа-к-функциям","link":"#ограничение-доступа-к-функциям","children":[]}],"relativePath":"3.x/ru/extend/backend/permissions.md","filePath":"3.x/ru/extend/backend/permissions.md"}'),r={name:"3.x/ru/extend/backend/permissions.md"};function u(k,s,d,g,h,m){const e=n("pre-heading"),t=n("post-heading");return o(),c("div",null,[a(e),s[0]||(s[0]=l("h1",null,"Разрешения",-1)),a(t),s[1]||(s[1]=i(`<p>Разрешения позволяют пользователям иметь определённые привилегии и функции в панели управления. Примером может быть возможность создавать или удалять записи, или просматривать журналы сервера. Эти разрешения основаны на назначенной роли и могут быть предоставлены на уровне отдельного пользователя.</p><h2 id="коды-разрешении"><a href="#коды-разрешении" class="header-anchor">#</a> Коды разрешений</h2><p>Коды разрешений определяют одно разрешение и являются строковыми ключами, использующими «точечную» нотацию, например <code>some.area.permission_name</code>. Эти разрешения предоставляются пользователям либо путём прямого назначения, либо через наследование от их роли.</p><p>При проверке наличия у пользователя конкретного разрешения разрешения его роли наследуются, а затем переопределяются разрешениями, назначенными непосредственно пользователю. Например:</p><ul><li>Если у пользователя <strong>Боб</strong> есть роль <strong>Genius</strong>; и</li><li>Роль <strong>Genius</strong> имеет разрешение <code>eat_cake</code>; но</li><li>У <strong>Боба</strong> разрешение <code>eat_cake</code> специально установлено как запрещённое; тогда</li><li><strong>Боб</strong> не сможет <code>eat_cake</code>.</li></ul><p>Однако:</p><ul><li>Если <strong>Бобу</strong> назначено разрешение <code>eat_vegetables</code> напрямую, но;</li><li>Роль <strong>Genius</strong> его не имеет, тогда;</li><li><strong>Боб</strong> всё равно получит <code>eat_vegetables</code>.</li></ul><h3 id="вложенные-разрешения"><a href="#вложенные-разрешения" class="header-anchor">#</a> Вложенные разрешения</h3><p>Коды разрешений поддерживают вложенную структуру для более чистого интерфейса при выборе разрешений. Для вложения кода разрешения «точечное» значение должно быть прямым потомком своего родителя, поддерживается неограниченная вложенность.</p><p>В следующем примере разрешение <code>manage_entries</code> должно быть предоставлено, чтобы коды <code>manage_entries.create</code> и <code>manage_entries.publish</code> стали доступными. Визуально это выглядит так:</p><pre class="dir-container"><code><p>├── manage_entries
|   ├── manage_entries.create
|   └── manage_entries.publish
└── delete_entries</p>
</code></pre><h2 id="уровни-доступа"><a href="#уровни-доступа" class="header-anchor">#</a> Уровни доступа</h2><p>Доступ ко всем частям экземпляра October CMS контролируется системой разрешений. Метод <code>BackendAuth::userHasAccess</code> — это быстрый способ проверить, авторизован ли текущий пользователь и имеет ли он разрешение на определённую область.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// Returns true if the user has permission</span>
<span class="token variable">$permissionGranted</span> <span class="token operator">=</span> <span class="token class-name static-context">BackendAuth</span><span class="token operator">::</span><span class="token function">userHasAccess</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;utilities.logs&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="суперпользователи"><a href="#суперпользователи" class="header-anchor">#</a> Суперпользователи</h3><p>Администраторам может быть присвоен специальный флаг «суперпользователь», который разрешает доступ ко всем областям. При его предоставлении система разрешений обходится, предоставляя доступ ко всем областям. Суперпользователи не видны другим обычным администраторам.</p><div class="custom-block warning"><p>Любой суперпользователь может создавать и удалять других суперпользователей, поэтому этот статус должен предоставляться только администратору высшего уровня или владельцу приложения.</p></div><h3 id="роли"><a href="#роли" class="header-anchor">#</a> Роли</h3><p>Роли используют модель <code>Backend\\Models\\UserRole</code> и являются группировками разрешений с именем и описанием для идентификации роли. Администратору может быть назначена только одна роль одновременно.</p><p>October CMS поставляется с двумя системными ролями по умолчанию: <code>developer</code> и <code>publisher</code>. Можно создать любое количество пользовательских ролей с собственными комбинациями разрешений и применить их к пользователям.</p><div class="custom-block tip"><p>Системные роли не могут изменять свои разрешения, однако их можно удалить, если они не нужны.</p></div><h3 id="иерархия-ролеи"><a href="#иерархия-ролеи" class="header-anchor">#</a> Иерархия ролей</h3><p>Каждой роли назначается ранговая позиция в панели управления, представленная столбцом <code>sort_order</code> в базе данных. Это позволяет установить базовую организационную структуру, при которой пользователи могут управлять только ролями ниже своей.</p><p>В следующем примере <strong>Старший редактор</strong> может управлять всеми пользователями, превосходя по рангу роли <strong>Штатный автор</strong> и <strong>Фактчекер</strong>. При этом роль <strong>Фактчекер</strong> не может видеть пользователей или управлять разрешениями выше неё — в ролях <strong>Штатный автор</strong> и <strong>Старший редактор</strong>.</p><ul><li>Старший редактор</li><li>Штатный автор</li><li>Фактчекер</li></ul><p>Если предоставлено разрешение <strong>Управление администраторами → Управление ролями</strong>, пользователи могут управлять своими пользователями, разрешениями и ролями, существующими ниже их текущей роли.</p><h2 id="регистрация-разрешении"><a href="#регистрация-разрешении" class="header-anchor">#</a> Регистрация разрешений</h2><p>Плагины могут регистрировать разрешения пользователей панели управления, переопределяя метод <code>registerPermissions</code> в <a href="./../extending.html">файле регистрации плагина</a>. Разрешения определяются как массив, где ключи соответствуют ключам разрешений, а значения — описаниям разрешений. Ключи разрешений состоят из имени автора, имени плагина и имени функции. Вот пример кода.</p><div class="language- extra-class"><pre class="language-text"><code>acme.blog.access_categories
</code></pre></div><p>Следующий пример показывает, как регистрировать элементы разрешений панели управления. Разрешения определяются ключом разрешения и описанием. В интерфейсе управления разрешениями панели управления разрешения отображаются как список флажков. Контроллеры панели управления могут использовать разрешения, определённые плагинами, для ограничения доступа пользователей к страницам или функциям.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">registerPermissions</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;acme.blog.access_posts&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;label&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Manage the blog posts&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;tab&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Blog&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;order&#39;</span> <span class="token operator">=&gt;</span> <span class="token number">200</span><span class="token punctuation">,</span>
        <span class="token punctuation">]</span><span class="token punctuation">,</span>
        <span class="token comment">// ...</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Вы также можете указать опцию <code>roles</code> как массив, где каждое значение — код API роли. Когда роль создаётся с этим кодом, она становится системной ролью, которая всегда предоставляет это разрешение пользователям с этой ролью.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">registerPermissions</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;acme.blog.access_categories&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;label&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Manage the blog categories&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;tab&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Blog&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;order&#39;</span> <span class="token operator">=&gt;</span> <span class="token number">200</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;roles&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;developer&#39;</span><span class="token punctuation">]</span>
        <span class="token punctuation">]</span>
        <span class="token comment">// ...</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h2 id="ограничение-доступа-к-страницам-панели-управления"><a href="#ограничение-доступа-к-страницам-панели-управления" class="header-anchor">#</a> Ограничение доступа к страницам панели управления</h2><p>В классе контроллера панели управления вы можете указать, какие разрешения необходимы для доступа к страницам контроллера. Это делается через свойство контроллера <code>$requiredPermissions</code>. Это свойство должно содержать массив ключей разрешений. Если разрешения пользователя совпадают с любым разрешением из списка, фреймворк позволит пользователю видеть страницы контроллера.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">namespace</span> <span class="token package">Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Controllers</span><span class="token punctuation">;</span>

<span class="token keyword">use</span> <span class="token package">Backend<span class="token punctuation">\\</span>Classes<span class="token punctuation">\\</span>BackendController</span><span class="token punctuation">;</span>

<span class="token keyword">class</span> <span class="token class-name-definition class-name">Posts</span> <span class="token keyword">extends</span> <span class="token class-name">BackendController</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token variable">$requiredPermissions</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;acme.blog.access_posts&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Вы также можете использовать символ <strong>звёздочки</strong> для обозначения условия «все разрешения». В следующем примере страницы контроллера доступны для всех пользователей, имеющих любые разрешения, начинающиеся со строки «acme.blog.»:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token variable">$requiredPermissions</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;acme.blog.*&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="ограничение-доступа-к-функциям"><a href="#ограничение-доступа-к-функциям" class="header-anchor">#</a> Ограничение доступа к функциям</h2><p>Модель пользователя панели управления имеет методы, позволяющие определить, имеет ли пользователь определённые разрешения. Вы можете использовать эту возможность для ограничения функциональности пользовательского интерфейса панели управления. Методы разрешений, поддерживаемые пользователем панели управления: <code>userHasAccess</code> и <code>userHasPermission</code>. Оба метода принимают два параметра: строку ключа разрешения (или массив строк ключей) и необязательный параметр, указывающий, что все разрешения, перечисленные первым параметром, обязательны.</p><p>Метод <code>userHasAccess</code> возвращает <strong>true</strong> для любого разрешения, если пользователь является суперпользователем. Метод <code>userHasPermission</code> более строг — возвращает true только если пользователь действительно имеет указанные разрешения в своей учётной записи или через роль. Как правило, <code>userHasAccess</code> является предпочтительным методом, так как он учитывает абсолютные полномочия суперпользователя. Следующий пример показывает использование методов в коде контроллера.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token class-name static-context">BackendAuth</span><span class="token operator">::</span><span class="token function">userHasAccess</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.blog.*&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// ...</span>
<span class="token punctuation">}</span>

<span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token class-name static-context">BackendAuth</span><span class="token operator">::</span><span class="token function">userHasPermission</span><span class="token punctuation">(</span><span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;acme.blog.access_posts&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;acme.blog.access_categories&#39;</span>
<span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// ...</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Вы также можете использовать эти методы в представлениях панели управления для скрытия элементов интерфейса. Следующий пример показывает, как скрыть кнопку в <a href="./../forms/form-controller.html">форме панели управления</a>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?php</span> <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token class-name static-context">BackendAuth</span><span class="token operator">::</span><span class="token function">userHasAccess</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.blog.delete_categories&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">:</span> <span class="token delimiter important">?&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span>
        <span class="token attr-name">type</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>button<span class="token punctuation">&quot;</span></span>
        <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>oc-icon-trash-o btn-icon danger<span class="token punctuation">&quot;</span></span>
        <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onDelete<span class="token punctuation">&quot;</span></span>
        <span class="token attr-name">data-load-indicator</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>Deleting Category...<span class="token punctuation">&quot;</span></span>
        <span class="token attr-name">data-request-confirm</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>Do you really want to delete this category?<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
<span class="token php language-php"><span class="token delimiter important">&lt;?php</span> <span class="token keyword">endif</span> <span class="token delimiter important">?&gt;</span></span>
</code></pre></div>`,44))])}const b=p(r,[["render",u]]);export{v as __pageData,b as default};
